from itertools import product

def solve_small_n(n):
    # a_i are the counts of k in b_0...b_n
    # b_k are the counts of k in a_0...a_n
    # Thus sum(a_i) = n+1 and sum(b_k) = n+1
    # Also a_i, b_k are in {0, ..., n+1}
    # Actually, a_i and b_k are in {0, ..., n+1}
    # But since their sum is n+1, they must be in {0, ..., n+1}

    # The values of a_i are determined by the distribution of b_k.
    # a_k = count of k in (b_0, ..., b_n)
    # b_k = count of k in (a_0, ..., a_n)

    # To search, we can iterate over all possible multiset distributions of a.
    # A distribution of a is a sequence (b_0, ..., b_n) such that sum(b_k) = n+1.
    # This is like placing n+1 balls into n+1 bins.

    import itertools

    def get_distributions(total, bins):
        # Generator for partitions of total into bins non-negative integers
        if bins == 1:
            yield (total,)
            return
        for i in range(total + 1):
            for rest in get_distributions(total - i, bins - 1):
                yield (i,) + rest

    results = []
    for b in get_distributions(n + 1, n + 1):
        # b is a potential sequence (b_0, ..., b_n)
        # Now compute the resulting sequence a:
        # a_k = count of k in b
        a = [0] * (n + 1)
        for val in b:
            if val <= n:
                a[val] += 1
            else:
                # if val > n, it's impossible since we only have indices 0...n
                # however, we should handle this.
                pass

        # Now check if this a produces the original b
        # b_k = count of k in a
        b_prime = [0] * (n + 1)
        for val in a:
            if val <= n:
                b_prime[val] += 1
            else:
                pass

        if list(b) == list(b_prime):
            # Found a good sequence pair (a, b)
            # Calculate sum_{i=0}^n (i+1) a_i^2
            s = sum((i + 1) * (a[i]**2) for i in range(n + 1))
            results.append(s)

    return set(results)

for n in range(1, 6):
    print(f"n={n}: {solve_small_n(n)}")

def solve_small_n_with_seq(n):
    import itertools
    def get_distributions(total, bins):
        if bins == 1:
            yield (total,)
            return
        for i in range(total + 1):
            for rest in get_distributions(total - i, bins - 1):
                yield (i,) + rest

    results = []
    for b in get_distributions(n + 1, n + 1):
        a = [0] * (n + 1)
        possible = True
        for val in b:
            if val <= n:
                a[val] += 1
            else:
                possible = False
                break
        if not possible: continue

        b_prime = [0] * (n + 1)
        for val in a:
            if val <= n:
                b_prime[val] += 1
            else:
                possible = False
                break
        if not possible: continue

        if list(b) == list(b_prime):
            s = sum((i + 1) * (a[i]**2) for i in range(n + 1))
            results.append((s, list(a)))

    return results

for n in range(1, 6):
